$p='css\main .css'; $css=[IO.File]::ReadAllText($p); $replacement=@'
@media (max-width: 900px) {
    .products-home {
        height: auto;
        min-height: 100vh;
    }

    .products-home .products-hero {
        height: 220px;
    }

    .products-home .search {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        padding: 15px 20px;
    }

    .products-home .search input:first-of-type,
    .products-home .search input:last-of-type {
        width: auto;
        min-width: 0;
        flex: 1 1 220px;
    }

    .all-card {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 20px;
        padding: 0 20px 30px;
    }

    .all-card .card-rpoduct {
        min-width: 0;
    }

    .all-card .card-rpoduct img {
        width: 100%;
        height: 130px;
    }
}

@media (max-width: 650px) {
    .products-home .products-hero {
        height: 170px;
    }

    .all-card {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 15px;
        padding: 0 12px 25px;
    }

    .all-card .card-rpoduct img {
        height: 115px;
    }

    .all-card .card-rpoduct h3 {
        font-size: 15px;
    }
}

@media (max-width: 400px) {
    .products-home .search {
        padding: 12px;
    }

    .products-home .search input:first-of-type,
    .products-home .search input:last-of-type {
        flex-basis: 100%;
        width: 100%;
    }

    .all-card {
        grid-template-columns: 1fr;
    }
}

'@; $pattern='(?s)@media \(max-width:500px\) \{.*?\}\r?\n\r?\n/\* about section \*/'; $result=[Text.RegularExpressions.Regex]::Replace($css,$pattern,$replacement+'/* about section */',1); if($result -eq $css){ throw 'Products media block was not found' }; [IO.File]::WriteAllText($p,$result)

$p='css\main .css'; $css=[IO.File]::ReadAllText($p); $append=@'

/* contact responsive layout */
@media (max-width: 1100px) {
    .contact {
        grid-template-columns: minmax(0, 1fr) minmax(220px, 0.75fr);
    }

    .contact-image {
        grid-column: 1 / -1;
        height: 300px;
    }

    .contact-info {
        align-items: center;
        padding: 30px 20px;
    }
}

@media (max-width: 700px) {
    .contact {
        display: flex;
        flex-direction: column;
    }

    .contact-content {
        margin: 0;
        padding: 55px 20px 20px;
    }

    .contact-content h2 {
        font-size: clamp(42px, 13vw, 60px);
    }

    .contact-content > p {
        max-width: 100%;
    }

    .contact-content .place {
        display: flex;
        flex-direction: column;
        gap: 15px;
    }

    .contact-content .place input,
    .contact-content .place textarea {
        box-sizing: border-box;
        width: 100%;
        margin: 0;
    }

    .contact-content .place textarea {
        min-height: 130px;
    }

    .contact-content .n3n {
        width: 100%;
        margin: 25px 0 10px;
    }

    .contact-info {
        align-items: stretch;
        gap: 16px;
        padding: 20px;
    }

    .contact-info .on {
        width: 100%;
        min-height: 70px;
    }

    .contact-image {
        height: 240px;
    }
}

@media (max-width: 400px) {
    .contact-content {
        padding-inline: 15px;
    }

    .contact-info {
        padding-inline: 15px;
    }

    .contact-image {
        height: 190px;
    }
}
'@; [IO.File]::AppendAllText($p,$append)
